solution:
module "reseau" {
  source  = "terraform-aws-modules/vpc/aws"
  version = "~> 5.0"
  cidr    = "10.0.0.0/16"
}

resource "aws_instance" "web" {
  subnet_id = module.reseau.subnet_id
}
